@app.route('/v1/models/dashscope', methods=['GET'])
@require_auth
def list_dashscope_models():
    """列出百炼全部可用模型（缓存5分钟）"""
    import time as _time
    cache = getattr(list_dashscope_models, '_cache', None)
    if cache and _time.time() - cache['ts'] < 300:
        return jsonify(cache['data'])

    try:
        resp = requests.get(f'{DASHSCOPE_BASE}/models',
            headers={'Authorization': f'Bearer {DASHSCOPE_KEY}'}, timeout=10)
        data = resp.json()
        list_dashscope_models._cache = {'ts': _time.time(), 'data': data}
        return jsonify(data)
    except Exception as e:
        if cache:
            return jsonify(cache['data'])
        return jsonify({'error': str(e)}), 500

